interface RouteMeta {
  title: string;
  description: string;
  h1?: string;
  intro?: string;
  /** AEO quick-answer block — rendered first in SSG content for crawler extraction */
  quickAnswerQ?: string;
  quickAnswerA?: string;
  sections?: string[];
  cities?: string[];
  /** Set to true for pages that shouldn't be indexed (e.g. internal search) */
  noIndex?: boolean;
  /** LCP hero image to preload for this specific route (avoids preloading it on every other page, since all routes share one index.html) */
  heroImage?: string;
  /**
   * Emit static Article JSON-LD (author: David Stein, publisher: the hub) into
   * the prerendered HTML. React Helmet adds the same schema client-side, but
   * crawlers that don't execute JavaScript — most AI engines — never see that.
   * The static copy lives inside #root so hydration replaces it, avoiding a
   * duplicate once React mounts.
   */
  article?: { datePublished: string; dateModified?: string };
  /** Question/answer pairs rendered as visible FAQ plus static FAQPage JSON-LD. */
  faq?: Array<{ q: string; a: string }>;
  /**
   * Prerender the live AFH for-sale inventory (summary table, listing cards,
   * ItemList JSON-LD) from src/data/afhListings.ts into the static HTML,
   * placed right after the quick answer. See src/data/afhInventoryPrerender.ts.
   */
  afhInventory?: AFHInventoryScope;
  /** Write the full guides and articles library (src/data/guideLibrary.ts) into the static HTML as grouped links. */
  guideLibrary?: boolean;
}

