  "/afh-club/training-education": {
    title: "AFH Training & Education | AFH Club | Real Property Planning",
    description: "Complete guide to Washington State AFH training requirements — 75-hour HCA training, AFH Administrator Training, specialty courses, continuing education, and where to enroll.",
    h1: "AFH Training & Education Requirements",
    quickAnswerQ: "What training is required to run an adult family home in Washington?",
    quickAnswerA: "Providers need 75-hour Home Care Aide training at a DSHS-approved program followed by the certification exam (unless exempt), the AFH Administrator Training course offered through community colleges contracted with DSHS (at least 48 hours; currently a 54-hour course), and current CPR and first-aid cards; safe food handling is part of the basic training. Providers must complete DSHS specialty training in dementia, mental health, or developmental disabilities before admitting residents with those needs. Providers and certified caregivers complete 12 hours of continuing education by their birthday each year.",
    intro: "Training runs on its own calendar, separate from the building and the application. Because courses fill and certification exams are scheduled, starting early is the difference between opening when the house is ready and waiting months after.",
    sections: [
      "Core requirements — 75-hour Home Care Aide training covering personal care, resident rights, communication, safety, and infection control; the certification exam and Department of Health credential; AFH Administrator Training; CPR and first aid from an authorized instructor; safe food handling, which is part of the basic training.",
      "Specialty training — The provider, entity representative, and resident manager must complete dementia, mental health, or developmental disabilities specialty training before admitting or serving residents with those needs, or within 120 days if a current resident develops one.",
      "Continuing education — 12 hours by each birthday for providers, entity representatives, resident managers, and certified caregivers.",
    ],
    faq: [
      { q: "Where do I take AFH Administrator Training?", a: "Through community colleges contracted with DSHS. Use the DSHS training finder (Other Training, AFH Administrator Training) to find current classes." },
      { q: "Do caregivers I hire need the same training?", a: "Non-exempt caregivers complete five hours of orientation and safety training before providing care, the 70-hour basic training within 120 days of hire, and Home Care Aide certification, and need DSHS name-and-date-of-birth and fingerprint background checks." },
    ],
    article: { datePublished: "2026-07-24", dateModified: "2026-09-28" },
  },
