/* Live-count tokens. A route with afhInventory may write {{live}}, {{active}},
   {{pending}}, {{cities}} or {{sold}} in its title, description, h1 or quick
   answer; they are filled from src/data/afhListings.ts at build time, so the
   count a searcher sees in the snippet is the count on the page. Search
   Console (Sept 2026) showed the for-sale phrases sitting at positions 8–13
   with 0–2% click-through; a snippet that leads with the number is what the
   competing results do. */
const plural = (n: number, one: string, many: string) => `${n} ${n === 1 ? one : many}`;
for (const meta of Object.values(ROUTE_METADATA)) {
  if (!meta.afhInventory) continue;
  const c = inventoryCounts(meta.afhInventory);
  const fill = (t?: string) =>
    t
      ?.replace(/\{\{live\}\}/g, String(c.live))
      .replace(/\{\{active\}\}/g, String(c.active))
      .replace(/\{\{pending\}\}/g, String(c.pending))
      .replace(/\{\{cities\}\}/g, String(c.cities))
      .replace(/\{\{sold\}\}/g, String(c.sold));
  const cityMatch = meta.description.match(/^\{\{live\}\} adult family homes for sale in ([^(]+?) \(\{\{active\}\} active, \{\{pending\}\} pending\) and \{\{sold\}\} closed sales with prices — (.*)$/s);
  if (cityMatch) {
    // City pages: small numbers, so the sentence is built to read correctly
    // at 0, 1 or many, and never says "0 adult family homes for sale".
    const [, city, tail] = cityMatch;
    const lead = c.live > 0
      ? `${plural(c.live, "adult family home", "adult family homes")} for sale in ${city} right now (${c.active} active, ${c.pending} pending)`
      : `Adult family homes in ${city} — no active listings at the moment`;
    const soldPart = c.sold > 0 ? `, ${plural(c.sold, "closed sale", "closed sales")} with prices` : "";
    meta.description = `${lead}${soldPart} — ${tail}`;
    meta.title = meta.title.replace(/ \(\{\{live\}\} on market\)/, c.live > 0 ? ` (${c.live} on market)` : "");
    continue;
  }
  if (c.live === 0) meta.title = meta.title.replace(/^\{\{live\}\} /, "");
  meta.title = fill(meta.title)!;
  meta.description = fill(meta.description)!;
  if (meta.h1) meta.h1 = fill(meta.h1);
  if (meta.quickAnswerA) meta.quickAnswerA = fill(meta.quickAnswerA);
}

const DEFAULT_SHELL_META: RouteMeta = ROUTE_METADATA["/"] || {
  title: "Real Property Planning | Washington State Real Estate Guidance",
  description:
    "Real Property Planning helps seniors, families, executors, trustees, attorneys, and fiduciaries navigate probate real estate, inherited homes, senior transitions, and housing change across Washington State.",
};

const replaceTag = (html: string, regex: RegExp, replacement: string) =>
  regex.test(html) ? html.replace(regex, replacement) : html;

const escHtml = (t: string) =>
  t.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
const jsonLdTag = (obj: unknown) =>
  `<script type="application/ld+json">${JSON.stringify(obj).replace(/</g, "\\u003c")}</script>`;

/* Static-page navigation (Sept 29, 2026). The prerendered #ssg-content is what
   crawlers read and what a visitor sees if the app's scripts fail to load (for
   example a browser holding an old copy right after a publish). It used to have
   no links at all, leaving that visitor stranded. Now it carries a small site
   header, a "you are here" trail and a back link. React replaces all of it once
   the app loads. */
const SSG_PARENTS: Array<[string, string, string]> = [
  ["/afh-club/", "/afh-club", "AFH Club"],
  ["/articles/", "/articles", "Featured Articles"],
  ["/guides/", "/guides-and-resources", "Guides & Articles"],
  ["/estate-probate-inherited-property/", "/estate-probate-inherited-property", "Estate, Probate & Inherited Property"],
  ["/executor-responsibilities-first-steps/", "/executor-responsibilities-first-steps", "Executor's First Steps"],
  ["/senior-living/", "/senior-transitions", "Senior Transitions"],
];
const ssgParentOf = (route: string): [string, string] => {
  const hit = SSG_PARENTS.find(([prefix, href]) => route.startsWith(prefix) && route !== href);
  return hit ? [hit[1], hit[2]] : ["/", "Home"];
};
const SSG_LINK = "color:#1B3A6B;text-decoration:underline;text-underline-offset:3px";
const ssgNav = (route: string) => {
  if (route === "/") return "";
  const [parentHref, parentLabel] = ssgParentOf(route);
  const top = [
    ["/", "Home"],
    ["/probate-estate-sales", "Estate & Probate"],
    ["/senior-transitions", "Senior Transitions"],
    ["/afh-club", "AFH Club"],
    ["/guides-and-resources", "Guides & Tools"],
    ["/contact", "Contact"],
  ]
    .map(([h, l]) => `<a href="${h}" style="${SSG_LINK};margin-right:14px;white-space:nowrap">${l}</a>`)
    .join("");
  const trail =
    parentHref === "/"
      ? `<a href="/" style="${SSG_LINK}">Home</a>`
      : `<a href="/" style="${SSG_LINK}">Home</a> › <a href="${parentHref}" style="${SSG_LINK}">${escHtml(parentLabel)}</a>`;
  return (
    `<div style="border-bottom:1px solid #e5e1da;padding:0 0 14px;margin:0 0 20px">` +
    `<a href="/" style="display:inline-block;font-weight:700;font-size:1.15rem;color:#1B3A6B;text-decoration:none;margin-bottom:8px">Real Property Planning</a>` +
    `<div role="navigation" aria-label="Site" style="font-size:0.95rem;line-height:2">${top}</div></div>` +
    `<p style="font-size:0.9rem;color:#555;margin:0 0 12px">${trail}</p>`
  );
};
/* AFH Club quick links (owner, Oct 1, 2026): the same seven as
   src/components/AFHClubQuickLinks.tsx, on every AFH Club page's static HTML,
   including the ~4,500 directory pages written below. */
const ssgAfhQuickLinks = () =>
  `<p style="margin:0 0 16px;line-height:2"><strong>AFH Club:</strong> ` +
  AFH_QUICK_LINKS.map((l) => `<a href="${l.href}" style="${SSG_LINK};margin-right:12px;white-space:nowrap">${escHtml(l.label)}</a>`).join("") +
  `</p>`;
const ssgBack = (route: string) => {
  if (route === "/") return "";
  const [parentHref, parentLabel] = ssgParentOf(route);
  return `<p style="margin:32px 0 0;padding-top:16px;border-top:1px solid #e5e1da"><a href="${parentHref}" style="${SSG_LINK};font-weight:600">‹ Back to ${escHtml(parentLabel)}</a></p>`;
};

const buildSsgContent = (meta: RouteMeta, route = "/") => {
  const { h1, intro, sections, cities, quickAnswerQ, quickAnswerA, faq, article, afhInventory } = meta;
  const inventory = afhInventory ? renderAfhInventory(afhInventory, route, h1 ?? meta.title, meta.description) : null;

  if (!h1 && !intro) return "";

  const ssgParts: string[] = [];
  ssgParts.push(`<div id="ssg-content" style="font-family:system-ui,sans-serif;max-width:800px;margin:0 auto;padding:40px 20px">`);
  ssgParts.push(ssgNav(route));
  if (isAFHClubPath(route)) ssgParts.push(ssgAfhQuickLinks());
  if (PROBATE_START_HERE_ROUTES.includes(route)) {
    const T = PROBATE_START_HERE;
    const l = (h: string, t: string) => `<a href="${h}" style="${SSG_LINK}">${escHtml(t)}</a>`;
    ssgParts.push(
      `<p style="background:#eef3f7;padding:10px 14px;margin:0 0 18px">` +
        `<strong>${escHtml(T.lead)}</strong> Start with the ${l(T.guide.href, T.guide.label)}, or look up terms like ` +
        `${l(T.terms[0].href, T.terms[0].label)} and ${l(T.terms[1].href, T.terms[1].label)} in the ${l(T.glossary.href, T.glossary.label)}.</p>`
    );
  }

  if (h1) ssgParts.push(`<h1 style="font-size:2rem;line-height:1.2;margin-bottom:16px">${h1}</h1>`);

  if (quickAnswerQ && quickAnswerA) {
    ssgParts.push(`<div style="margin-bottom:24px;padding:20px;border:1px solid #e5e5e5;border-radius:12px;background:#fafafa">`);
    ssgParts.push(`<p style="font-size:0.75rem;font-weight:700;letter-spacing:0.15em;text-transform:uppercase;color:#a8892f;margin:0 0 8px 0">Quick Answer</p>`);
    ssgParts.push(`<h2 style="font-size:1.25rem;line-height:1.3;margin:0 0 8px 0">${quickAnswerQ}</h2>`);
    ssgParts.push(`<p style="font-size:1.05rem;line-height:1.7;color:#444;margin:0">${quickAnswerA}</p>`);
    ssgParts.push(`</div>`);
  }

  if (inventory) ssgParts.push(inventory.html);

  if (intro) ssgParts.push(`<p style="font-size:1.1rem;line-height:1.7;color:#444">${intro}</p>`);

  if (meta.guideLibrary) ssgParts.push(guideLibraryHtml(escHtml));

  if (sections) {
    sections.forEach((s) => {
      const [heading, ...rest] = s.split(" — ");
      ssgParts.push(`<h2 style="font-size:1.3rem;margin-top:24px;margin-bottom:8px">${heading}</h2>`);
      if (rest.length) ssgParts.push(`<p style="color:#555;line-height:1.6">${rest.join(" — ")}</p>`);
    });
  }

  if (faq && faq.length) {
    ssgParts.push(`<h2 style="font-size:1.3rem;margin-top:24px;margin-bottom:8px">Common questions</h2>`);
    faq.forEach(({ q, a }) => {
      ssgParts.push(`<h3 style="font-size:1.1rem;margin:16px 0 6px">${escHtml(q)}</h3>`);
      ssgParts.push(`<p style="color:#555;line-height:1.6;margin:0">${escHtml(a)}</p>`);
    });
  }

  if (article) {
    ssgParts.push(
      `<p style="margin-top:24px;color:#555;line-height:1.6"><strong>About the author:</strong> David Stein is a Washington State licensed real estate broker (eXp Realty, license #133972) and a Washington State certified residential appraiser (Stein Appraisal, license #1702080). <a href="/about" style="color:#1a365d">More about David</a>.</p>`
    );
  }

  ssgParts.push(`<div style="margin-top:28px;padding:20px;border:1px solid #e5e5e5;border-radius:8px;background:#fafafa">`);
  ssgParts.push(`<h2 style="font-size:1.2rem;margin:0 0 12px 0">Real Property Planning</h2>`);
  ssgParts.push(`<p style="margin:4px 0;color:#444">Independent hub for probate, estate &amp; senior transition real estate in Washington State</p>`);
  ssgParts.push(`<p style="margin:4px 0;color:#444">David Stein — Washington State Licensed Real Estate Broker — David Stein's real estate license is held under eXp Realty</p>`);
  ssgParts.push(`<p style="margin:4px 0;color:#444">Washington State Certified Residential Appraiser — Stein Appraisal</p>`);
  ssgParts.push(`<p style="margin:4px 0;color:#555">Phone: <a href="tel:2069003015" style="color:#1a365d">(206) 900-3015</a></p>`);
  ssgParts.push(`<p style="margin:4px 0;color:#555">Email: <a href="mailto:info@realpropertyplanning.com" style="color:#1a365d">info@realpropertyplanning.com</a></p>`);
  ssgParts.push(`<p style="margin:4px 0;color:#555">Mailing Address: PO Box 1462, Woodinville, WA 98072</p>`);
  ssgParts.push(`<p style="margin:4px 0;color:#555">Office: 1455 NW Leary Way, Seattle, WA 98107</p>`);
  ssgParts.push(`</div>`);

  ssgParts.push(`<div style="margin-top:28px">`);
  ssgParts.push(`<h2 style="font-size:1.3rem;margin-bottom:12px">Washington State Service Areas</h2>`);
  if (cities && cities.length > 0) {
    ssgParts.push(`<p style="color:#555;line-height:1.8">${cities.join(" · ")}</p>`);
  }
  ssgParts.push(`<p style="color:#666;margin-top:8px;line-height:1.6">A free educational resource covering all of Washington State.</p>`);
  ssgParts.push(`</div>`);

  const canonical = route === "/" ? SITE_URL : `${SITE_URL}${route}`;
  if (article) {
    ssgParts.push(
      jsonLdTag({
        "@context": "https://schema.org",
        "@type": "Article",
        headline: h1 ?? meta.title,
        description: meta.description,
        url: canonical,
        mainEntityOfPage: canonical,
        datePublished: article.datePublished,
        dateModified: article.dateModified ?? article.datePublished,
        author: articleAuthor,
        publisher: articlePublisher,
        isPartOf: { "@type": "WebSite", name: "Real Property Planning", url: SITE_URL },
      })
    );
  }
  if (inventory) inventory.jsonLd.forEach((obj) => ssgParts.push(jsonLdTag(obj)));
  if (faq && faq.length) {
    ssgParts.push(
      jsonLdTag({
        "@context": "https://schema.org",
        "@type": "FAQPage",
        mainEntity: faq.map(({ q, a }) => ({
          "@type": "Question",
          name: q,
          acceptedAnswer: { "@type": "Answer", text: a },
        })),
      })
    );
  }

  ssgParts.push(ssgBack(route));
  ssgParts.push(`</div>`);
  return ssgParts.join("");
};

const buildRouteAwareShellScript = () => {
  // Build a compact JSON map of route -> {title, description, h1, intro, quickAnswerQ, quickAnswerA}
  // This is embedded inline so no XHR is needed (Lovable hosting returns root index.html for all paths)
  const routeMap: Record<
    string,
    { t: string; d: string; h1?: string; intro?: string; qQ?: string; qA?: string; ni?: 1 }
  > = {};
  for (const [route, meta] of Object.entries(ROUTE_METADATA)) {
    routeMap[route] = {
      t: meta.title,
      d: meta.description,
      ...(meta.h1 ? { h1: meta.h1 } : {}),
      ...(meta.intro ? { intro: meta.intro } : {}),
      ...(meta.quickAnswerQ ? { qQ: meta.quickAnswerQ } : {}),
      ...(meta.quickAnswerA ? { qA: meta.quickAnswerA } : {}),
      ...(meta.noIndex ? { ni: 1 } : {}),
    };
  }
  const mapJson = JSON.stringify(routeMap);

  return `<script>(function(){
var R=${mapJson};
var normalizePath=function(p){var n=p||"/";try{n=decodeURIComponent(n);}catch(e){}if(!n.startsWith("/"))n="/"+n;if(n.endsWith("/index.html"))n=n.slice(0,-11)||"/";if(n.length>1&&n.endsWith("/"))n=n.slice(0,-1);return n||"/";};
var route=normalizePath(window.location.pathname);
/* index.html is the homepage, prerendered in full (data-prerendered). The host
   also serves it for routes without their own file; there it must not show the
   homepage, and main.tsx must render fresh rather than hydrate it. */
var root0=document.getElementById("root");
if(route!=="/"&&root0&&root0.hasAttribute("data-prerendered")){root0.removeAttribute("data-prerendered");root0.innerHTML="";}
var m=R[route];
if(!m)return;
if(m.t)document.title=m.t;
var setMeta=function(sel,attr,val){var el=document.querySelector(sel);if(el)el.setAttribute(attr,val);else{el=document.createElement("meta");var parts=sel.match(/\\[([^=]+)="([^"]+)"\\]/);if(parts){el.setAttribute(parts[1],parts[2]);}el.setAttribute(attr,val);document.head.appendChild(el);}};
setMeta('meta[name="description"]',"content",m.d);
setMeta('meta[name="robots"]',"content",m.ni?"noindex,follow":"index,follow");
setMeta('meta[property="og:title"]',"content",m.t);
setMeta('meta[property="og:description"]',"content",m.d);
setMeta('meta[name="twitter:title"]',"content",m.t);
setMeta('meta[name="twitter:description"]',"content",m.d);
var canon=route==="/"?"${SITE_URL}":"${SITE_URL}"+route;
setMeta('meta[property="og:url"]',"content",canon);
var link=document.querySelector('link[rel="canonical"]');if(link)link.setAttribute("href",canon);else{link=document.createElement("link");link.rel="canonical";link.href=canon;document.head.appendChild(link);}
var root=document.getElementById("root");
if(root&&!root.hasAttribute("data-prerendered")&&m.h1&&!document.getElementById("ssg-content")){var html='<div id="ssg-content" style="font-family:system-ui,sans-serif;max-width:800px;margin:0 auto;padding:40px 20px">';
html+='<p style="margin:0 0 18px;padding-bottom:12px;border-bottom:1px solid #e5e1da"><a href="/" style="font-weight:700;color:#1B3A6B;text-decoration:none">Real Property Planning</a> · <a href="/afh-club" style="color:#1B3A6B">AFH Club</a> · <a href="/guides-and-resources" style="color:#1B3A6B">Guides</a> · <a href="/contact" style="color:#1B3A6B">Contact</a></p>';
html+='<h1 style="font-size:2rem;line-height:1.2;margin-bottom:16px">'+m.h1+'</h1>';
if(m.qQ&&m.qA){html+='<div style="margin:20px 0;padding:20px;border:1px solid #e2e2e2;border-radius:12px;background:#fafaf8"><p style="font-weight:700;text-transform:uppercase;letter-spacing:0.1em;font-size:0.7rem;color:#a8892f;margin:0 0 6px 0">Quick Answer</p><h2 style="font-size:1.25rem;line-height:1.3;margin:0 0 8px 0">'+m.qQ+'</h2><p style="font-size:1.05rem;line-height:1.7;color:#444;margin:0">'+m.qA+'</p></div>';}
if(m.intro){html+='<p style="font-size:1.1rem;line-height:1.7;color:#444">'+m.intro+'</p>';}
html+='</div>';root.innerHTML=html;}
})();</script>`;
};

const injectRouteAwareShell = (html: string) => {
  const script = buildRouteAwareShellScript();
  // Insert script right after </head><body> or before the closing </body>
  // Since SSG content may already be inside #root, match the closing </div> of #root
  return html.replace("</body>", `${script}</body>`);
};

/* ── Full page content for crawlers (Oct 4, 2026) ───────────────────────────
   Most AI crawlers do not run JavaScript; they read only this static file.
   The metadata summary (buildSsgContent) left many pages at ~120 words of menu
   and footer. After the browser build, the app is bundled for Node
   (src/entry-server.tsx) and each ROUTE_METADATA page is rendered to HTML,
   which replaces the summary inside #root (marked data-prerendered, so
   main.tsx hydrates it). The summary's JSON-LD (Article, FAQPage, …) moves to
   <head>; JSON-LD a page adds itself through Helmet is added when its @type is
   not already present. Any failure — the whole step or one
   page — falls back to the summary, so the build never breaks over it. */
type RenderedPage = { html: string; jsonLd: string[] };

const LD_JSON = /<script[^>]*application\/ld\+json[^>]*>[\s\S]*?<\/script>/g;
const ldType = (script: string) => script.match(/"@type"\s*:\s*"([^"]+)"/)?.[1] ?? "";
const visibleWords = (html: string) =>
  html.replace(/<script[\s\S]*?<\/script>|<style[\s\S]*?<\/style>/g, " ").replace(/<[^>]+>/g, " ").split(/\s+/).filter(Boolean).length;

/** The rendered page for #root, and the JSON-LD to put in <head> (kept out of
 * #root so the browser can hydrate the page exactly). null = keep the summary. */
/** A preload for the page's high-priority image (the homepage hero),
 * so the browser requests it from <head> instead of waiting to reach the <img>
 * in the body (Oct 7, 2026). Empty when the page has none. */
const heroPreload = (html: string) => {
  const img = html.match(/<img\b[^>]*fetchpriority="high"[^>]*>/i)?.[0];
  if (!img) return "";
  const attr = (n: string) => img.match(new RegExp(`\\s${n}="([^"]*)"`, "i"))?.[1];
  const src = attr("src");
  if (!src) return "";
  const set = attr("srcset");
  const sizes = attr("sizes");
  /* Added by a tiny script rather than a plain <link>, and only on "/": the host
     also serves the homepage file (index.html) for addresses that have no file
     of their own, and those pages should not download the homepage photo. The
     script runs while <head> is read, so the request still starts early. Only
     the homepage has a high-priority image today; if another page gets one,
     widen the path check. */
  const js = (v?: string) => JSON.stringify(v ?? "");
  return `<script>(function(){var p=location.pathname;if(p!=="/"&&p!=="/index.html")return;var l=document.createElement("link");l.rel="preload";l.as="image";l.href=${js(src)};${set ? `l.setAttribute("imagesrcset",${js(set)});` : ""}${sizes ? `l.setAttribute("imagesizes",${js(sizes)});` : ""}l.setAttribute("fetchpriority","high");document.head.appendChild(l);})();</script>`;
};

const withRenderedPage = (ssgContent: string, page: RenderedPage) => {
  // A page that renders thinner than its summary (a redirect, an empty shell) keeps the summary.
  if (visibleWords(page.html) < visibleWords(ssgContent)) return null;
  const keep: string[] = [...(ssgContent.match(LD_JSON) ?? [])];
  const types = new Set(keep.map(ldType));
  const extra = page.jsonLd.filter((sc) => !types.has(ldType(sc)) && !keep.includes(sc));
  // Tagged so main.tsx can remove them at startup: in the browser, Helmet renders the
  // page's own JSON-LD, and a second copy would duplicate it (e.g. two FAQPage blocks).
  const tagged = [...keep, ...extra].map((sc) => sc.replace("<script", "<script data-prerender-ld"));
  return { body: page.html, jsonLd: tagged.join("\n  "), preload: heroPreload(page.html) };
};

const renderPagesForCrawlers = async (routes: string[]): Promise<Map<string, RenderedPage>> => {
  const pages = new Map<string, RenderedPage>();
  const started = Date.now();
  try {
    const { build } = await import("vite");
    const outDir = path.resolve(__dirname, "node_modules/.cache/rpp-ssr");
    await build({
      configFile: false,
      root: __dirname,
      logLevel: "error",
      publicDir: false,
      plugins: [react()],
      resolve: { alias: { "@": path.resolve(__dirname, "./src") } },
      build: {
        ssr: "src/entry-server.tsx",
        outDir,
        emptyOutDir: true,
        ssrEmitAssets: false,
        rollupOptions: { output: { format: "esm", inlineDynamicImports: true, entryFileNames: "entry-server.mjs" } },
      },
      ssr: { noExternal: true },
    });
    const mod = await import(`${pathToFileURL(path.join(outDir, "entry-server.mjs")).href}?t=${Date.now()}`);
    // The app logs layout-effect warnings on the server; they are expected (effects run in the browser).
    const error = console.error;
    console.error = () => {};
    const failed: string[] = [];
    try {
      for (let i = 0; i < routes.length; i += 8) {
        await Promise.all(
          routes.slice(i, i + 8).map(async (route) => {
            try {
              pages.set(route, await mod.render(route));
            } catch {
              failed.push(route);
            }
          })
        );
      }
    } finally {
      console.error = error;
    }
    console.log(`full-page-render: ${pages.size} pages rendered in ${Math.round((Date.now() - started) / 1000)}s${failed.length ? `; kept the summary for ${failed.length}: ${failed.join(", ")}` : ""}`);
  } catch (err) {
    console.warn(`full-page-render: skipped, every page keeps its metadata summary (${String((err as Error)?.message ?? err).slice(0, 300)})`);
  }
  return pages;
};

const applyMetadata = (
  html: string,
  route: string,
  meta: RouteMeta,
  options: { injectSsg?: boolean; ssr?: RenderedPage } = {}
) => {
  const { title, description } = meta;
  const { injectSsg = true, ssr } = options;
  const canonical = route === "/" ? SITE_URL : `${SITE_URL}${route}`;
  const robotsContent = meta.noIndex ? "noindex,follow" : "index,follow";

  let out = html;
  out = out.replace(/<title>[\s\S]*?<\/title>/i, `<title>${title}</title>`);
  out = replaceTag(
    out,
    /<meta\s+name="robots"\s+content="[\s\S]*?"\s*\/?>/i,
    `<meta name="robots" content="${robotsContent}" />`
  );
  out = replaceTag(
    out,
    /<meta\s+name="description"\s+content="[\s\S]*?"\s*\/?>/i,
    `<meta name="description" content="${description}" />`
  );
  out = replaceTag(
    out,
    /<meta\s+property="og:title"\s+content="[\s\S]*?"\s*\/?>/i,
    `<meta property="og:title" content="${title}" />`
  );
  out = replaceTag(
    out,
    /<meta\s+property="og:description"\s+content="[\s\S]*?"\s*\/?>/i,
    `<meta property="og:description" content="${description}" />`
  );
  out = replaceTag(
    out,
    /<meta\s+name="twitter:title"\s+content="[\s\S]*?"\s*\/?>/i,
    `<meta name="twitter:title" content="${title}" />`
  );
  out = replaceTag(
    out,
    /<meta\s+name="twitter:description"\s+content="[\s\S]*?"\s*\/?>/i,
    `<meta name="twitter:description" content="${description}" />`
  );
  out = replaceTag(
    out,
    /<link\s+rel="canonical"\s+href="[\s\S]*?"\s*\/?>/i,
    `<link rel="canonical" href="${canonical}" />`
  );
  out = replaceTag(
    out,
    /<meta\s+property="og:url"\s+content="[\s\S]*?"\s*\/?>/i,
    `<meta property="og:url" content="${canonical}" />`
  );
  if (meta.heroImage && out.includes("</head>")) {
    out = out.replace(
      "</head>",
      `  <link rel="preload" as="image" href="${meta.heroImage}" fetchpriority="high" />\n  </head>`
    );
  }

  if (injectSsg) {
    const ssgContent = buildSsgContent(meta, route);
    const page = ssr ? withRenderedPage(ssgContent, ssr) : null;
    // Function replacements, so "$" in page text (prices) is never read as a pattern.
    if (page) {
      out = out.replace('<div id="root"></div>', () => `<div id="root" data-prerendered>${page.body}</div>`);
      if (page.jsonLd) out = out.replace("</head>", () => `${page.jsonLd}\n  </head>`);
      // First thing in <head>, ahead of the stylesheet: an inline script placed
      // after a stylesheet waits for it to download before running.
      if (page.preload) out = out.replace('<meta charset="UTF-8" />', (m) => `${m}\n    ${page.preload}`);
    } else if (ssgContent) {
      out = out.replace('<div id="root"></div>', () => `<div id="root">${ssgContent}</div>`);
    }
  }

  return out;
};

/**
 * Write a prerendered route as <route>/index.html. The host serves that file
 * for the clean URL (confirmed on the live site via a variant marker, Sept
 * 2026); a parallel <route>.html copy used to be written as well, which doubled
 * the file count of every build for no benefit.
 */
const writeRouteHtml = async (distDir: string, route: string, routeHtml: string) => {
  const directoryIndexPath = path.join(distDir, route.slice(1), "index.html");
  await mkdir(path.dirname(directoryIndexPath), { recursive: true });
  await writeFile(directoryIndexPath, routeHtml, "utf8");
};


/** The site's public MCP endpoint (Supabase edge function "mcp"), from supabase/config.toml. */
const MCP_PUBLIC_URL = (() => {
  try {
    const ref = readFileSyncForStats(path.resolve(__dirname, "supabase/config.toml"), "utf8").match(/project_id\s*=\s*"([^"]+)"/)?.[1];
    return ref ? `https://${ref}.supabase.co/functions/v1/mcp` : "";
  } catch {
    return "";
  }
})();

/**
 * AFH Club professionals as JSON. src/data/afhProfessionals.ts imports images
 * and "@/" paths, so Node cannot load it directly: bundle it with esbuild,
 * turning each image import into its file name, then import the bundle.
 */
const loadAfhProfessionalsForAi = async () => {
  const { build } = await import("esbuild");
  const src = path.resolve(__dirname, "src");
  const out = await build({
    entryPoints: [path.join(src, "data/afhProfessionals.ts")],
    bundle: true,
    write: false,
    format: "esm",
    platform: "node",
    logLevel: "silent",
    alias: { "@": src },
    plugins: [
      {
        name: "image-stub",
        setup(b) {
          b.onLoad({ filter: /\.(webp|png|jpe?g|svg|gif)$/ }, (a) => ({ contents: `export default ${JSON.stringify(path.basename(a.path))};`, loader: "js" }));
        },
      },
    ],
  });
  const mod = await import(`data:text/javascript;base64,${Buffer.from(out.outputFiles[0].text).toString("base64")}`);
  return (mod.ACTIVE_AFH_PROFESSIONAL_GROUPS as Array<{ id: string; label: string; profession: string; people: Array<Record<string, string | undefined>> }>).map((g) => ({
    group: g.label,
    profession: g.profession,
    people: g.people.map((p) => ({
      name: p.name,
      title: p.title,
      company: p.company,
      ...(p.license ? { license: p.license } : {}),
      ...(p.phone ? { phone: p.phone } : {}),
      ...(p.email ? { email: p.email } : {}),
      ...(p.website ? { website: p.website } : {}),
      specialty: p.specialty,
      ...(p.note ? { note: p.note } : {}),
      ...(p.morePath ? { page: SITE_URL + p.morePath } : {}),
    })),
  }));
};

const writeAiData = async (distDir: string) => {
  const dataDir = path.resolve(__dirname, "src/data/afh");
  const dir = path.join(distDir, "ai");
  await mkdir(dir, { recursive: true });
  const generated = new Date().toISOString();
  const wrap = (data: unknown) => JSON.stringify({ version: AI_DATA_VERSION, generated, data });
  const pages = buildAiPages(ROUTE_METADATA);
  const glossary = buildAiGlossary();
  const stats = buildAiStats(dataDir);
  const listings = buildAiListingsOverview();
  const directory = buildAiDirectory(dataDir);
  let professionals: unknown = [];
  try {
    professionals = {
      page: `${SITE_URL}/afh-club/find-a-professional`,
      standard:
        "Listed because the site owner has met them personally. Not endorsements or referrals. Nobody pays to be listed and Real Property Planning receives nothing if someone hires them, except the featured broker, who is paid a commission if hired.",
      groups: await loadAfhProfessionalsForAi(),
    };
  } catch (err) {
    console.warn("ai-data: professionals.json skipped", err);
  }
  const files: Record<string, string> = {
    "pages.json": wrap(pages),
    "glossary.json": wrap(glossary),
    "afh-rule-changes.json": wrap(buildAiRuleChanges()),
    "afh-stats.json": wrap(stats),
    "afh-directory.json": wrap({
      source: "DSHS Adult Family Home Locator (public record)",
      retrieved: stats.retrievedTo,
      dshsRecordsUrlPattern: DSHS_RECORDS_URL_PATTERN,
      homes: directory,
    }),
    "afh-listings-overview.json": wrap(listings),
    "afh-professionals.json": wrap(professionals),
    "guide-library.json": wrap(buildAiGuideLibrary()),
  };
  for (const [name, body] of Object.entries(files)) await writeFile(path.join(dir, name), body, "utf8");
  const llmsInput = { pages, glossary, stats, listings, mcpUrl: MCP_PUBLIC_URL };
  await writeFile(path.join(distDir, "llms.txt"), buildLlmsTxt(llmsInput), "utf8");
  await writeFile(path.join(distDir, "llms-full.txt"), buildLlmsFullTxt(llmsInput), "utf8");
  console.log(`ai-data: ${Object.keys(files).length} JSON files (${pages.length} pages, ${glossary.length} terms, ${directory.length} homes), llms.txt, llms-full.txt`);
};

const routeMetadataPlugin = {
  name: "route-metadata-prerender",
  apply: "build" as const,
  async closeBundle() {
    const distDir = path.resolve(__dirname, "dist");
    const baseHtmlPath = path.join(distDir, "index.html");
    let baseHtml: string;

    try {
      baseHtml = await readFile(baseHtmlPath, "utf8");
    } catch {
      return;
    }

    /* City directory pages (/afh-club/homes/<city> and its filter pages) are
       rendered in full too (Oct 7, 2026), with the city's data loaded first
       (src/entry-server.tsx), so phones see the whole page at once instead of
       a text summary that React then replaced, which made the page jump
       (layout shift ~0.1). Facility pages (slug ends in the license number)
       and county pages keep the summary. */
    const directoryRoutes = buildAfhDirectoryRoutes(path.resolve(__dirname, "src/data/afh"));
    const cityPageRoutes = directoryRoutes
      .map((r) => r.route)
      .filter((r) => /^\/afh-club\/homes\/[a-z0-9-]+(\/[a-z0-9-]+)?$/.test(r) && !r.startsWith("/afh-club/homes/county/") && !/-\d{6}$/.test(r));
    const rendered = await renderPagesForCrawlers([...Object.keys(ROUTE_METADATA), ...cityPageRoutes]);

    const rootHtml = injectRouteAwareShell(
      applyMetadata(baseHtml, "/", DEFAULT_SHELL_META, { injectSsg: true, ssr: rendered.get("/") })
    );
    await writeFile(baseHtmlPath, rootHtml, "utf8");

    await Promise.all(
      Object.entries(ROUTE_METADATA)
        .filter(([route]) => route !== "/")
        .map(async ([route, metadata]) => {
          const routeHtml = applyMetadata(baseHtml, route, metadata, { ssr: rendered.get(route) });
          await writeRouteHtml(distDir, route, routeHtml);
        })
    );

    /* Adult family home directory — hub, city, filter, and facility pages.
       These routes come from src/data/afh, not ROUTE_METADATA, so they are
       prerendered from the data (see src/data/afh/prerender.ts). Written in
       batches: ~4,500 routes, and writing them all concurrently exhausts file
       handles on some CI runners. */
    const BATCH = 200;
    for (let i = 0; i < directoryRoutes.length; i += BATCH) {
      await Promise.all(
        directoryRoutes.slice(i, i + BATCH).map(async ({ route, title, description, body }) => {
          const base = applyMetadata(baseHtml, route, { title, description }, { injectSsg: false });
          const ssr = rendered.get(route);
          const page = ssr ? withRenderedPage(body, ssr) : null;
          const routeHtml = page
            ? base
                .replace('<div id="root"></div>', () => `<div id="root" data-prerendered>${page.body}</div>`)
                .replace("</head>", () => `${page.jsonLd}\n  </head>`)
                .replace('<meta charset="UTF-8" />', (m) => (page.preload ? `${m}\n    ${page.preload}` : m))
            : base.replace('<div id="root"></div>', () => `<div id="root"><div style="max-width:800px;margin:0 auto;padding:16px 20px 0;font-family:system-ui,sans-serif">${ssgAfhQuickLinks()}</div>${body}</div>`);
          await writeRouteHtml(distDir, route, routeHtml);
        })
      );
    }
    console.log(`route-metadata-prerender: ${directoryRoutes.length} AFH directory routes written`);

    /* Permanent per-listing pages for the AFH for-sale inventory
       (/afh-club/listings/<city>-<source>-<number>). Generated from
       src/data/afhListings.ts, including sold / expired records so a listing's
       URL keeps resolving after it leaves the market. See
       src/data/afhInventoryPrerender.ts. */
    const cityRoutes = afhCityRoutes();
    for (const [route, meta] of Object.entries(ROUTE_METADATA)) {
      if (meta.afhInventory?.city && !cityRoutes[meta.afhInventory.city.toLowerCase()]) {
        throw new Error(`${route} has afhInventory.city "${meta.afhInventory.city}" but src/data/afhCityPages.ts has no entry for it.`);
      }
    }
    const listingRoutes = buildAfhListingRoutes(cityRoutes, loadAllFacilities(path.resolve(__dirname, "src/data/afh")));
    await Promise.all(
      listingRoutes.map(async ({ route, title, description, body }) => {
        const routeHtml = applyMetadata(baseHtml, route, { title, description }, { injectSsg: false }).replace(
          '<div id="root"></div>',
          `<div id="root"><div style="max-width:800px;margin:0 auto;padding:16px 20px 0;font-family:system-ui,sans-serif">${ssgAfhQuickLinks()}</div>${body}</div>`
        );
        await writeRouteHtml(distDir, route, routeHtml);
      })
    );
    console.log(`route-metadata-prerender: ${listingRoutes.length} AFH listing pages written`);

    /* Add the listing pages to the built sitemap. public/sitemap.xml is the
       hand-maintained source; the generated block lives only in dist so it is
       always in step with the data. */
    const sitemapPath = path.join(distDir, "sitemap.xml");
    try {
      const START = "  <!-- BEGIN afh-listings (generated at build from src/data/afhListings.ts) -->";
      const END = "  <!-- END afh-listings -->";
      let sitemap = await readFile(sitemapPath, "utf8");
      const block = [
        START,
        ...listingRoutes.map(
          ({ route, lastmod }) =>
            `  <url><loc>${SITE_URL}${route}</loc><lastmod>${lastmod}</lastmod><changefreq>weekly</changefreq><priority>0.7</priority></url>`
        ),
        END,
      ].join("\n");
      // dist/sitemap.xml is a fresh copy of public/sitemap.xml on every build, so the block is never already present.
      sitemap = sitemap.replace("</urlset>", `${block}\n</urlset>`);
      await writeFile(sitemapPath, sitemap, "utf8");
    } catch {
      console.warn("route-metadata-prerender: sitemap.xml not found in dist; listing URLs not added");
    }

    /* Split the built sitemap into three files behind a sitemap index (Sept 27, 2026).
       public/sitemap.xml stays the single hand-maintained source that
       scripts/check-sitemap.mjs and scripts/generate-directory-sitemap.mjs work on;
       only dist/ is split. Google Search Console reports indexing per file, so the
       ~4,500 directory pages no longer bury the signal for the guides.
         sitemap-main.xml          Real Property Planning (family side)
         sitemap-afh-club.xml      AFH Club guides, tools, listings hubs
         sitemap-afh-directory.xml licensed-home directory, individual listings, city for-sale pages
       robots.txt keeps pointing at /sitemap.xml, which becomes the index. */
    try {
      const xml = await readFile(sitemapPath, "utf8");
      const head = xml.slice(0, xml.indexOf(">", xml.indexOf("<urlset")) + 1);
      const entries = [...xml.matchAll(/<url>[\s\S]*?<\/url>/g)].map((m) => m[0]);
      const pathOf = (e: string) => (e.match(/<loc>https?:\/\/[^/<]+([^<]*)<\/loc>/)?.[1] || "/");
      const LISTING_HUBS = new Set(["properties", "businesses", "for-lease"]);
      const bucket = (p: string) => {
        if (p === "/afh-club/homes" || p.startsWith("/afh-club/homes/") || p.startsWith("/afh-club/for-sale/")) return "afh-directory";
        const listing = p.match(/^\/afh-club\/listings\/([^/]+)$/);
        if (listing && !LISTING_HUBS.has(listing[1])) return "afh-directory";
        if (p === "/afh-club" || p.startsWith("/afh-club/") || p === "/afh-submit") return "afh-club";
        return "main";
      };
      const files: Record<string, string[]> = { main: [], "afh-club": [], "afh-directory": [] };
      for (const e of entries) files[bucket(pathOf(e))].push(e);
      const today = new Date().toISOString().slice(0, 10);
      const index: string[] = [];
      for (const [name, list] of Object.entries(files)) {
        const file = `sitemap-${name}.xml`;
        await writeFile(path.join(distDir, file), `${head}\n${list.join("\n")}\n</urlset>\n`, "utf8");
        const lastmod = list.map((e) => e.match(/<lastmod>([^<]+)<\/lastmod>/)?.[1] || "").sort().pop() || today;
        index.push(`  <sitemap><loc>${SITE_URL}/${file}</loc><lastmod>${lastmod}</lastmod></sitemap>`);
        console.log(`route-metadata-prerender: ${file} — ${list.length} URLs`);
      }
      await writeFile(
        sitemapPath,
        `<?xml version="1.0" encoding="UTF-8"?>\n<sitemapindex xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n${index.join("\n")}\n</sitemapindex>\n`,
        "utf8"
      );
    } catch (err) {
      console.warn("route-metadata-prerender: sitemap split skipped; dist/sitemap.xml left whole", err);
    }

    /* Real 301s. The host (Netlify or Cloudflare) reads dist/_redirects and
       answers an old address with a permanent redirect before any JavaScript
       runs. Source of truth: src/data/redirects.ts (Sept 27, 2026). Pattern
       redirects (":name" parts) go last so exact addresses win. */
    {
      const exact = REDIRECTS.filter((r) => !r.from.includes(":"));
      const patterns = REDIRECTS.filter((r) => r.from.includes(":"));
      const body = [
        "# Generated at build from src/data/redirects.ts. Do not edit dist/_redirects by hand.",
        ...[...exact, ...patterns].map((r) => `${r.from} ${r.to} 301`),
      ].join("\n");
      await writeFile(path.join(distDir, "_redirects"), body + "\n", "utf8");
      console.log(`route-metadata-prerender: _redirects — ${REDIRECTS.length} permanent redirects`);

      /* Lovable's host ignores _redirects (httpstatus.io, Sept 29, 2026: all
         three test addresses answered 200 with the homepage's HTML and a
         canonical pointing at the homepage). So each exact old address also
         gets a tiny forwarding page: an instant meta refresh (Google treats a
         0-second refresh as a permanent redirect), a canonical to the new
         address, noindex, and a script fallback. Pattern redirects can't get
         files; the in-app <Navigate> routes still cover those. */
      const esc = (s: string) => s.replace(/&/g, "&amp;").replace(/"/g, "&quot;").replace(/</g, "&lt;");
      for (const r of exact) {
        const url = `${SITE_URL}${r.to}`;
        const html = `<!doctype html>
<html lang="en"><head><meta charset="utf-8">
<title>Moved | Real Property Planning</title>
<meta name="robots" content="noindex,follow">
<link rel="canonical" href="${esc(url)}">
<meta http-equiv="refresh" content="0; url=${esc(url)}">
<script>location.replace(${JSON.stringify(r.to)} + location.search + location.hash);</script>
</head><body><p>This page has moved to <a href="${esc(url)}">${esc(url)}</a>.</p></body></html>
`;
        await writeRouteHtml(distDir, r.from, html);
      }
      console.log(`route-metadata-prerender: ${exact.length} forwarding pages for old addresses`);
    }

    /* AI-readable data (Oct 1, 2026): dist/ai/*.json, dist/llms.txt, dist/llms-full.txt.
       Built from the same data the pages use; the public MCP server fetches the
       JSON from the live site. See src/lib/aiData.ts (and its NWMLS note). */
    await writeAiData(distDir);
  },
};

